"""Six successive, runnable milestones of one graduation reference project."""
import json
from write_media_data_network import ROOT, DATA, entry, emit, task, question

SCOPE='连续参考项目为“阅读搭子”。学生可以自选题，但须提交同样的需求、核心流程和测试证据。课堂支架只留本课缺口，前课结构已给；Starter无积木。未做Android真机测试，编译、设计器截图不代表持久化或系统分享已在手机验收。'

def milestone(n,scope,states,flow,tasks,exits,blocks,**extra):
    spec=json.loads((ROOT.parent/'aia'/f'lesson{n:02}'/'artifact-spec.json').read_text(encoding='utf8'))
    captures={i:dict(target=target,title=blocks[i][0],body=blocks[i][1]) for i,target in enumerate(spec['screenshotGroups'])}
    entry(n,SCOPE+' '+scope,states,flow,tasks,exits,[x[2] for x in blocks],capture_overrides=captures,**extra)

